export abstract class CFileHandler {

	abstract get op(): string

	// ..........................................................
	// ASYNC

	abstract canHandle(
			path: string,
			hOptions: hash
			): Promise<boolean>

	// ..........................................................

	async isNeeded(
			path: string,
			hOptions: hash = {}
			): AutoPromise<boolean> {

		const lOutPaths = this.allOutPaths(path)
		if (lOutPaths.length === 0) {
			return true
		}
		else {
			for (const outPath of lOutPaths) {
				if (!newerDestFileExists(path, outPath)) {
					return true
				}
			}
			return false
		}
	}

	// ..........................................................

	allOutPaths(
			path: string,
			hOptions: hash = {}
			): string[] {

		// --- by default, returns an empty array
		//     so handle() will be called
		return []
	}

	// ..........................................................
	// ASYNC

	abstract handle(
			path: string,
			hOptions: hash
			): Promise<TExecResult>

	// ..........................................................
	// ASYNC

	async postProcess(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		return {
			success: true,
			notNeeded: true,   // --- no post processing was done
			timeTaken: 0
			}
	}

	// ..........................................................
	// ASYNC

	async handleFile(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const timer = new CTimer()
		try {
			assert(isFile(path), `No such file: ${path}`)
			const canHandle = await this.canHandle(path, hOptions)
			if (!canHandle) {
				const stderr = `${this.op} can't handle '${path}'`
				ERR(stderr)
				return {
					success: false,
					timeTaken: timer.timeTaken(),
					infile: toRelPath(path),
					stderr
					}
			}

			const force = ('force' in hOptions) && hOptions.force
			DBG(`force = ${force}`)
			const needed = await this.isNeeded(path, hOptions)
			if (!needed && !force) {
				DBG(`${this.op} not needed`)
				return {
					success: true,
					notNeeded: true,
					timeTaken: timer.timeTaken(),
					infile: toRelPath(path)
					}
			}

			const hResult = await this.handle(path, hOptions)

			if (!('outfile' in hResult)) {
				const lOutFiles = this.allOutPaths(path, hOptions)
				if (lOutFiles.length === 1) {
					Object.assign(hResult, {outfile: toRelPath(lOutFiles[0])})
				}
				else if (lOutFiles.length > 1) {
					const lRelPaths = lOutFiles.map((path) => toRelPath(path))
					Object.assign(hResult, {outfile: lRelPaths})
				}
			}

			if (!hOptions.nopp) {
				const hPostResult = await this.postProcess(path, hOptions)
				if (!('notNeeded' in hPostResult)) {
					Object.assign(hPostResult, {timeTaken: timer.timeTaken()})
					Object.assign(hResult, {hPostResult})
				}
			}

			return Object.assign(hResult, {
				infile: toRelPath(path),
				timeTaken: timer.timeTaken()
				})
		}

		catch (err) {
			const stderr = getErrStr(err)
			DBG(`${this.op}: err = ${stderr}`)
			return {
				success: false,
				timeTaken: timer.timeTaken(),
				infile: toRelPath(path),
				stderr
				}
		}
	}

	// ..........................................................
	// SYNC

	getOutput(hResult: TExecResult): string {

		return (hResult?.stdout || '') + (hResult?.stderr || '')
	}
}

