// ASYNC

export const cmdIsInstalled = async (scriptName: string): AutoPromise<boolean> => {

	const homeDir = Deno.env.get("HOME") ?? Deno.env.get("USERPROFILE") ?? ""
	const ext = (Deno.build.os === "windows") ? ".cmd" : ""
	const path = `${homeDir}/.deno/bin/${scriptName}${ext}`
	const isThere = await exists(path)
	if (isThere) {
		const fileInfo = await Deno.stat(path)
		return fileInfo.isFile
	}
	else {
		return false
	}
}

// ---------------------------------------------------------------------------

export const getCmdName = (
		path: string,
		hOptions: hash
		): string => {

	if (('name' in hOptions) && (typeof hOptions.name === 'string')) {
		return hOptions.name as string
	}
	else {
		return parsePath(path).stub.replaceAll('.', '_')
	}
}

// ---------------------------------------------------------------------------

class CCmdInstaller extends CFileHandler {

	get op() {
		return 'doInstallCmd'
	}

	async canHandle(
			path: string,
			hOptions: hash = {}
			) {
		return path.endsWith('.cmd.ts')
	}

	async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const name = getCmdName(path, hOptions)
		return await execCmd('deno', [
			'install',
			'--global',
			'--force',
			'--config', 'deno.json',
			'-A',
			'--name', name,
			path
			])
	}
}

export const doInstallCmd = new CCmdInstaller()

// ---------------------------------------------------------------------------

class CCmdUninstaller extends CFileHandler {

	get op() {
		return 'doUninstallCmd'
	}

	// ..........................................................

	async canHandle(
			path: string,
			hOptions: hash = {}
			) {

		return path.endsWith('.cmd.ts')
	}

	// ..........................................................

	override async isNeeded(
			path: string,
			hOptions: hash = {}
			): AutoPromise<boolean> {

		const name = getCmdName(path, hOptions)
		return await cmdIsInstalled(name)
	}

	// ..........................................................

	async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const name = getCmdName(path, hOptions)
		return await execCmd('deno', [
			'uninstall',
			'-g',
			name
			])
	}
}

export const doUninstallCmd = new CCmdUninstaller()

